  this.carryDelay += delay;
  unlock.forEach((id) => this.unlock(id));
  continue;
}
if (kind === 'sys' && !thread) thread = this.lastThread || this.speaker;
if (!thread) thread = this.speaker || 'unknown';
this.pending = {
